/**
 * Reader's vendored rendering libraries (#653): the raw source strings the
 * Plugin carries, the nested pdf.js core Worker, and the promise that loading
 * the Plugin entry evaluates nothing. Provenance lives in `vendor/README.md`;
 * the strings are regenerated by `node scripts/vendor-reader.mjs`.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { runInThisContext } from "node:vm";
import { afterEach, describe, expect, it, vi } from "vitest";
import {
  PDF_CORE_INLINE_FLAG,
  classicPdfCoreSource,
  foliateSource,
  pdfCoreInlineRequested,
  pdfCoreSource,
  pdfDisplaySource,
  pdfViewerCss,
  purifySource,
  startPdfCore,
  withPdfPolyfills,
} from "./loaders";
import pdfWorkerSource from "./vendor/pdfjs/pdf.worker.min.mjs?raw";
import pdfPolyfillSource from "./vendor/pdfjs/polyfills.min.js?raw";

/** The pdf.js release the vendored sources must carry. */
const PDFJS_VERSION = "6.5.438";

/** The Mozilla licence banner both pdf.js modules start with. */
const PDFJS_BANNER = "/**\n * @licstart";

/** Both pdf.js sources as Reader ships them: the polyfills, then pdf.js intact. */
function expectPolyfilledPdfjs(source: string): void {
  expect(source.startsWith(`${pdfPolyfillSource}\n${PDFJS_BANNER}`)).toBe(true);
}

/** A Blob that keeps its parts, so the test can read the source it wrapped. */
class RecordedBlob {
  constructor(
    readonly parts: string[],
    readonly options?: BlobPropertyBag
  ) {}
}

/** A Worker that records how it was started instead of running anything. */
class RecordedWorker {
  readonly terminate = vi.fn();
  constructor(
    readonly url: string,
    readonly options?: WorkerOptions
  ) {
    workers.push(this);
  }
}

/** Every Worker started through the stubbed global. */
const workers: RecordedWorker[] = [];
/** Every Blob handed to `URL.createObjectURL`. */
const blobs: RecordedBlob[] = [];

/** The `blob:` URL `startPdfCore` gives each Blob, in creation order. */
const CORE_URL = "blob:pdfjs-core";
const BOOTSTRAP_URL = "blob:pdfjs-bootstrap";

/** Stubs the Worker, Blob, and object-URL globals `startPdfCore` needs. */
function stubWorkerGlobals(): {
  createObjectURL: ReturnType<typeof vi.fn>;
  revokeObjectURL: ReturnType<typeof vi.fn>;
} {
  workers.length = 0;
  blobs.length = 0;
  const createObjectURL = vi.fn((blob: RecordedBlob) => {
    blobs.push(blob);
    return blobs.length === 1 ? CORE_URL : BOOTSTRAP_URL;
  });
  const revokeObjectURL = vi.fn();
  vi.stubGlobal("Blob", RecordedBlob);
  vi.stubGlobal("Worker", RecordedWorker);
  vi.stubGlobal("URL", { createObjectURL, revokeObjectURL });
  return { createObjectURL, revokeObjectURL };
}

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("vendored source strings", () => {
  it("carries the pdf.js display module, banner and version intact", () => {
    const source = pdfDisplaySource();
    expect(source.length).toBeGreaterThan(100_000);
    expectPolyfilledPdfjs(source);
    expect(source).toContain(PDFJS_VERSION);
  });

  it("carries the pdf.js core worker, banner and version intact", () => {
    const { createObjectURL } = stubWorkerGlobals();
    const core = startPdfCore();
    expect(createObjectURL).toHaveBeenCalledTimes(2);
    const [coreBlob] = blobs;
    expect(coreBlob.options?.type).toBe("text/javascript");
    const [source] = coreBlob.parts;
    expect(source.length).toBeGreaterThan(1_000_000);
    expectPolyfilledPdfjs(source);
    expect(source).toContain(PDFJS_VERSION);
    // A classic Worker cannot parse the module's `export` or `import.meta`;
    // `classicPdfCoreSource` removes both.
    expect(source).not.toMatch(/\bexport\s*\{/);
    expect(source).not.toContain("import.meta");
    core.dispose();
  });

  it("starts the core from a classic bootstrap that importScripts it by blob: URL", () => {
    stubWorkerGlobals();
    const core = startPdfCore();
    const [, bootstrapBlob] = blobs;
    expect(bootstrapBlob.options?.type).toBe("text/javascript");
    const [bootstrap] = bootstrapBlob.parts;
    expect(bootstrap).toContain(`importScripts(${JSON.stringify(CORE_URL)});`);
    expect(bootstrap).toContain("self.pdfjsWorker.WorkerMessageHandler.initializeFromPort(port)");
    expect(bootstrap).toContain("port.start()");
    core.dispose();
  });

  it("carries pdf.js's viewer CSS, text layer rules included", () => {
    const css = pdfViewerCss();
    expect(css.startsWith("/* Copyright 2014 Mozilla Foundation")).toBe(true);
    expect(css).toContain(".textLayer");
  });

  it("carries the foliate parsers as code, not as a comment", () => {
    const source = foliateSource();
    expect(source.length).toBeGreaterThan(10_000);
    expect(source).toMatch(/^[\w$]/);
  });

  it("carries DOMPurify's browser build as code", () => {
    const source = purifySource();
    expect(source.length).toBeGreaterThan(50_000);
    // The build opens with its licence banner, which the Frame's `blob:` module
    // keeps; the code follows it.
    expect(source.replace(/^\s*\/\*[\s\S]*?\*\//, "").trim()).toMatch(/^[\w$]/);
    expect(source).toContain("DOMPurify");
  });
});

describe("startPdfCore", () => {
  it("starts a classic Worker from the bootstrap's blob: URL", () => {
    stubWorkerGlobals();
    const core = startPdfCore();
    expect(workers).toHaveLength(1);
    expect(core.worker).toBe(workers[0]);
    expect(workers[0].url).toBe(BOOTSTRAP_URL);
    // A module Worker cannot fetch its script from a `blob:` URL in the
    // sandbox's opaque origin, so the Worker must be classic.
    expect(workers[0].options).toBeUndefined();
    core.dispose();
  });

  it("terminates the Worker and releases both blob: URLs on dispose", () => {
    const { revokeObjectURL } = stubWorkerGlobals();
    const core = startPdfCore();
    expect(workers[0].terminate).not.toHaveBeenCalled();
    core.dispose();
    expect(workers[0].terminate).toHaveBeenCalledTimes(1);
    expect(revokeObjectURL).toHaveBeenCalledWith(CORE_URL);
    expect(revokeObjectURL).toHaveBeenCalledWith(BOOTSTRAP_URL);
  });

  it("is nested by default: no flag and no option starts a Worker", () => {
    stubWorkerGlobals();
    expect(pdfCoreInlineRequested()).toBe(false);
    const core = startPdfCore();
    expect(workers).toHaveLength(1);
    core.dispose();
  });

  it("runs inline only when the spike flag is set, and then starts no Worker", () => {
    const { revokeObjectURL } = stubWorkerGlobals();
    (globalThis as Record<string, unknown>)[PDF_CORE_INLINE_FLAG] = true;
    try {
      expect(pdfCoreInlineRequested()).toBe(true);
      const core = startPdfCore();
      expect(workers).toHaveLength(0);
      // The inline core loads with the same classic importScripts as the nested
      // one, so it carries the same rewrite of the module-only constructs.
      expect(blobs).toHaveLength(1);
      expect(blobs[0].parts).toEqual([withPdfPolyfills(classicPdfCoreSource(pdfWorkerSource))]);
      core.dispose();
      expect(revokeObjectURL).toHaveBeenCalledWith(CORE_URL);
    } finally {
      delete (globalThis as Record<string, unknown>)[PDF_CORE_INLINE_FLAG];
    }
  });

  it("an explicit inline option overrides the flag's default", () => {
    stubWorkerGlobals();
    const core = startPdfCore({ inline: true });
    expect(workers).toHaveLength(0);
    core.dispose();
  });
});

describe("the foliate bundle", () => {
  it("exports the parser surface Reader needs from one self-contained module", async () => {
    const source = foliateSource();
    const url = `data:text/javascript;base64,${Buffer.from(source).toString("base64")}`;
    const module = (await import(/* @vite-ignore */ url)) as Record<string, unknown>;
    expect(Object.keys(module).sort()).toEqual([
      "CFI",
      "EPUB",
      "MOBI",
      "isMOBI",
      "makeComicBook",
      "makeFB2",
      "search",
      "unzlibSync",
    ]);
    expect(typeof module.EPUB).toBe("function");
    expect(typeof module.MOBI).toBe("function");
    expect(typeof module.isMOBI).toBe("function");
    expect(typeof module.makeFB2).toBe("function");
    expect(typeof module.makeComicBook).toBe("function");
    expect(typeof module.search).toBe("function");
    expect(typeof module.unzlibSync).toBe("function");
    expect(module.CFI).toBeTypeOf("object");
  });
});

describe("the Plugin entry", () => {
  it("starts no Worker when the entry and its loaders load", async () => {
    const WorkerSpy = vi.fn();
    vi.stubGlobal("Worker", WorkerSpy);
    await import("./loaders");
    await import("./index");
    expect(WorkerSpy).not.toHaveBeenCalled();
  });
});

/** The slice of the vendored pdf.js display module this test drives. */
interface VendoredPdfjs {
  PDFWorker: new () => { destroy(): Promise<void> };
  GlobalWorkerOptions: { workerSrc: string };
  getDocument(params: Record<string, unknown>): {
    promise: Promise<{
      numPages: number;
      getPage(pageNumber: number): Promise<{
        getTextContent(): Promise<{ items: { str?: string }[] }>;
      }>;
    }>;
    destroy(): Promise<void>;
  };
}

describe("the Android core turn", () => {
  it("opens a PDF from globalThis.pdfjsWorker with no port and no workerSrc", async () => {
    const scope = globalThis as unknown as { self?: unknown; pdfjsWorker?: unknown };
    const hadSelf = "self" in globalThis;
    scope.self ??= globalThis;
    try {
      // On Android the Frame has no Worker to start, so the Worker sends the
      // core's source and the Frame evaluates it as a classic script
      // (reader.js `loadPdfCore`); loaders ships the polyfills at its head.
      runInThisContext(pdfCoreSource());
      expect(scope.pdfjsWorker).toBeDefined();

      // The display module the Frame imports, built exactly as the Worker sends
      // it: the polyfills, then pdf.js intact.
      const url = `data:text/javascript;base64,${Buffer.from(pdfDisplaySource()).toString("base64")}`;
      const pdfjs = (await import(/* @vite-ignore */ url)) as unknown as VendoredPdfjs;
      // No port, and nothing to fall back to: an empty workerSrc means only the
      // global the core defined can answer the document.
      pdfjs.GlobalWorkerOptions.workerSrc = "";
      const worker = new pdfjs.PDFWorker();
      const task = pdfjs.getDocument({
        data: new Uint8Array(readFileSync(join(__dirname, "fixtures", "twelve-pages.pdf"))),
        worker,
        isEvalSupported: false,
      });
      try {
        const document = await task.promise;
        expect(document.numPages).toBe(12);
        const page = await document.getPage(3);
        const content = await page.getTextContent();
        expect(content.items.map((item) => item.str ?? "").join("")).toContain("3");
      } finally {
        await task.destroy();
      }
    } finally {
      delete scope.pdfjsWorker;
      if (!hadSelf) delete scope.self;
    }
  });
});
